N = 10 ** 5 + 10

class Bit:

	def __init__(self, n):
		self.n = n
		self.arr = [0] * (n + 1)

	def update(self, i, v):
		i += 1
		while i <= self.n:
			self.arr[i] += v
			i += i & -i

	def getsum(self, i):
		s = 0
		i = i + 1
		while i > 0:
			s += self.arr[i]
			i -= i & -i
		return s

	def print(self):
		print(self.arr)

def horizontal(x1, y1, x2, y2):
	return y1 == y2

def main():
	tc = int(input())
	allowed = []
	blocked = []
	hevents = []
	vevents = []
	hendpoints = {}
	vendpoints = {}
	ans = [-1] * tc
	for t in range(tc):
		(x1, y1, x2, y2) = tuple(map(int, input().split()))
		if horizontal(x1, y1, x2, y2):
			if x1 > x2:
				(x1, x2) = (x2, x1)
			vevents.append((y1, (x1, x2), 'Q', t))
			hevents.append((x1, y1, 'A'))
			hevents.append((x2, y2, 'S'))
			hendpoints[x1, y1] = 1
			hendpoints[x2, y2] = 1
		else:
			if y1 > y2:
				(y1, y2) = (y2, y1)
			hevents.append((x1, (y1, y2), 'Q', t))
			vevents.append((y1, x1, 'A'))
			vevents.append((y2, x2, 'S'))
			vendpoints[y1, x1] = 1
			vendpoints[y2, x2] = 1
	hevents.sort(key=lambda x: (x[0], x[2]))
	vevents.sort(key=lambda x: (x[0], x[2]))
	bh = Bit(N)
	for e in hevents:
		if e[2] == 'A':
			bh.update(e[1], 1)
		if e[2] == 'Q':
			start = e[1][0] - 1
			end = e[1][1]
			if (e[0], start + 1) in hendpoints:
				start += 1
			if (e[0], end) in hendpoints:
				end -= 1
			sum1 = bh.getsum(end)
			sum2 = bh.getsum(start)
			ans[e[3]] = sum1 - sum2
		if e[2] == 'S':
			bh.update(e[1], -1)
	bv = Bit(N)
	for e in vevents:
		if e[2] == 'A':
			bv.update(e[1], 1)
		if e[2] == 'Q':
			start = e[1][0] - 1
			end = e[1][1]
			if (e[0], start + 1) in vendpoints:
				start += 1
			if (e[0], end) in vendpoints:
				end -= 1
			sum1 = bv.getsum(end)
			sum2 = bv.getsum(start)
			ans[e[3]] = sum1 - sum2
		if e[2] == 'S':
			bv.update(e[1], -1)
	total = sum(ans) // 2
	print(total)
	print(*ans, sep=' ')
main()
